function curlPost($url, $postData, $post = 1)
{
    $curl = curl_init();
    curl_setopt($curl, CURLOPT_POST, $post);

    curl_setopt($curl, CURLOPT_URL, $url);
    curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
